package com.townyreborn.staffconnector;
import java.nio.file.*;import java.io.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
/** Reads new WARN/ERROR records from the fixed local log; no chat/command ingestion. */
final class LogDiagnostics implements AutoCloseable {
 private final Path file=Path.of("logs/latest.log");private final Consumer<Map<String,Object>> sink;private final TelemetryBuffer stats;private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"TR-LogDiagnostics");t.setDaemon(true);return t;});private long offset;private Object identity;
 LogDiagnostics(Consumer<Map<String,Object>> sink,TelemetryBuffer stats){this.sink=sink;this.stats=stats;try{offset=Files.size(file);identity=Files.readAttributes(file,java.nio.file.attribute.BasicFileAttributes.class).fileKey();}catch(IOException ignored){}worker.scheduleWithFixedDelay(this::read,10,10,TimeUnit.SECONDS);}
 private void read(){try{if(!Files.isRegularFile(file))return;Object key=Files.readAttributes(file,java.nio.file.attribute.BasicFileAttributes.class).fileKey();long size=Files.size(file);if(!Objects.equals(identity,key)||size<offset){offset=0;identity=key;}try(RandomAccessFile in=new RandomAccessFile(file.toFile(),"r")){in.seek(offset);for(int i=0;i<2000;i++){long start=in.getFilePointer();String line=in.readLine();if(line==null)break;if(in.getFilePointer()==size){long end=in.getFilePointer();in.seek(Math.max(0,end-1));int last=in.read();in.seek(end);if(last!=10&&last!=13){in.seek(start);break;}}String text=new String(line.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1),java.nio.charset.StandardCharsets.UTF_8);Object parsed=parse(text);if(parsed instanceof Map<?,?> m){String plugin=String.valueOf(m.get("plugin"));stats.record(plugin,"log_"+String.valueOf(m.get("level")).toLowerCase(Locale.ROOT),"",null,"","",1,Map.of());@SuppressWarnings("unchecked") Map<String,Object> payload=(Map<String,Object>)m;sink.accept(payload);}}offset=in.getFilePointer();}}catch(IOException|RuntimeException ignored){}}
 static Map<String,Object> parse(String line){if(!line.matches("^\\[[0-9:]+.*(?:WARN|ERROR).*"))return null;if(line.matches("(?i).*(issued server command|password|passwd|api.token|bottoken|secret.key|authorization|bearer |tr_live_).*"))return null;String level=line.contains("ERROR")?"ERROR":"WARN",plugin="Server";var m=java.util.regex.Pattern.compile("\\]: \\[([^]]+)\\]").matcher(line);if(m.find())plugin=m.group(1);else{m=java.util.regex.Pattern.compile("\\[([^] ]+)\\]:").matcher(line);if(m.find())plugin=m.group(1);}String clean=line.replaceAll("(?<![0-9])(?:[0-9]{1,3}\\.){3}[0-9]{1,3}(?![0-9])","[IP]").replaceAll("[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}","[UUID]");return Map.of("type","diagnostic.alert","plugin",TelemetryBuffer.clean(plugin,96),"level",level,"message",TelemetryBuffer.clean(clean,1600));}
 @Override public void close(){worker.shutdownNow();}
}
